{
  "questions": [
    {
      "n": 1,
      "start": "Wie hat sich die Maturitätsquote im Kanton Baselland",
      "end": "(aufgeschlüsselt nach allgemeiner und Berufs/Fach-Matura) in den letzten 10 Jahren entwickelt?"
    },
    {
      "n": 2,
      "start": "Wie vergleicht sich die aktuelle Maturitätsquote",
      "end": "mit derjenigen in anderen grösseren Kantonen der Deutschschweiz?"
    },
    {
      "n": 3,
      "start": "Welcher Prozentsatz der Maturanden schliesst später ein Studium ab?",
      "end": "Wie hat sich diese Quote in den letzten Jahren entwickelt?"
    },
    {
      "n": 4,
      "start": "Die Berufs/Fachmatura kann man während/nach der Lehre abschliessen, aber auch durch den",
      "end": "ausschliesslichen Besuch einer vom Staat getragenen Schule (z.B. FMS, WMS, etc.). Wie hoch sind die Anteile dieser beiden Wege und wie haben sie sich entwickelt?"
    },
    {
      "n": 5,
      "start": "Für welche Berufsabschlüsse/Weiterausbildungen, die in der Vergangenheit ohne Matura",
      "end": "erreicht werden konnten, sind in den letzten 10 Jahren ein Maturabschluss defacto bzw. dejure zur Pflicht geworden?"
    },
    {
      "n": 6,
      "start": "Welche Mittel stünden dem Staat für eine allfällige \"Regulierung\" der Maturitätsquote zur",
      "end": "Verfügung?"
    },
    {
      "n": 7,
      "start": "Welche Position/Politik verfolgt die Regierung bezüglich der Maturitätsquote?",
      "end": "?"
    },
    {
      "n": 8,
      "start": "Für die Umsetzung der entsprechenden Politik ist die sogenannte Laufbahnverordnung der",
      "end": "BKSD massgebend. Welche Änderungen sind in dieser Verordnung geplant?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "In der Bildungsstatistik wird unter Maturitätsquote häufig die Summe von Berufsmaturitätsquote",
      "end": "und Gymnasialmaturitätsquote verstanden."
    },
    {
      "n": 2,
      "start": "Die Berufsmaturitätsquote liegt im Kanton Basel-Landschaft um 0.6% über dem schweizerischen",
      "end": "Durchschnittswert (2013)."
    },
    {
      "n": 3,
      "start": "Die Studienerfolgsquote auf Bachelorstufe beträgt an den universitären Hochschulen 66%. Sie",
      "end": "unterscheidet sich nach Fachbereich: Geistes- und Sozialwissenschaft 69%; Wirtschaftswissenschaften 63%; Recht 68%; Exakte und Naturwissenschaften 64%; Technische Wissenschaften 65%; Interdisziplinäre und andere 70% (Eintrittskohorte Schweiz 2007; BFS 2013)."
    },
    {
      "n": 4,
      "start": "Die Anzahl Abschlüsse einer Berufsmaturität I ist rund doppelt so hoch wie die Anzahl",
      "end": "Abschlüsse der Berufsmaturität II."
    },
    {
      "n": 5,
      "start": "null",
      "end": "null"
    },
    {
      "n": 6,
      "start": "null",
      "end": "null"
    },
    {
      "n": 7,
      "start": "Eine „Regulierung“ der Maturitätsquote ist kein Gegenstand des Regierungsprogramms 2012–2015",
      "end": "des Kantons Basel-Landschaft."
    },
    {
      "n": 8,
      "start": "null",
